import{_ as e,o as l,c as t,a5 as i}from"./chunks/framework.BPFk9-tb.js";const r="/assets/handwriting.D-TZC_vb.jpg",_=JSON.parse('{"title":"硬笔字-笔画","description":"","frontmatter":{"date":"2019-04-26T09:25:51","title":"硬笔字-笔画"},"headers":[{"level":3,"title":"点：如高峰坠石","slug":"点-如高峰坠石","link":"#点-如高峰坠石","children":[]},{"level":3,"title":"横：如千里阵云","slug":"横-如千里阵云","link":"#横-如千里阵云","children":[]},{"level":3,"title":"竖：如万岁枯藤","slug":"竖-如万岁枯藤","link":"#竖-如万岁枯藤","children":[]},{"level":3,"title":"撇：如陆断犀象","slug":"撇-如陆断犀象","link":"#撇-如陆断犀象","children":[]},{"level":3,"title":"捺：如崩浪雷奔","slug":"捺-如崩浪雷奔","link":"#捺-如崩浪雷奔","children":[]},{"level":3,"title":"折：如劲弩筋节","slug":"折-如劲弩筋节","link":"#折-如劲弩筋节","children":[]},{"level":3,"title":"提：如策马扬鞭","slug":"提-如策马扬鞭","link":"#提-如策马扬鞭","children":[]},{"level":3,"title":"勾：如百钧弩发","slug":"勾-如百钧弩发","link":"#勾-如百钧弩发","children":[]}],"relativePath":"posts/misc/handwriting.md","filePath":"posts/misc/handwriting.md"}'),n={name:"posts/misc/handwriting.md"};function s(h,a,o,d,c,p){return l(),t("div",null,[...a[0]||(a[0]=[i('<h3 id="点-如高峰坠石" tabindex="-1">点：如高峰坠石 <a class="header-anchor" href="#点-如高峰坠石" aria-label="Permalink to &quot;点：如高峰坠石&quot;">​</a></h3><p>右点是写好点的基础，空中落笔，不可太长。垂点像露珠，仰点是自左上到右下落笔顿笔后往左路上挑。</p><h3 id="横-如千里阵云" tabindex="-1">横：如千里阵云 <a class="header-anchor" href="#横-如千里阵云" aria-label="Permalink to &quot;横：如千里阵云&quot;">​</a></h3><p>起笔要稳，略顿，收笔要顿笔回锋。长横要舒展，行笔速度稍快，中间微微上凸。短横顶着斜向上。</p><h3 id="竖-如万岁枯藤" tabindex="-1">竖：如万岁枯藤 <a class="header-anchor" href="#竖-如万岁枯藤" aria-label="Permalink to &quot;竖：如万岁枯藤&quot;">​</a></h3><p>垂露竖起笔向左上方伸出，顿笔下行，轻顿收笔。悬针竖运笔沉着形如银针，中锋行笔。</p><h3 id="撇-如陆断犀象" tabindex="-1">撇：如陆断犀象 <a class="header-anchor" href="#撇-如陆断犀象" aria-label="Permalink to &quot;撇：如陆断犀象&quot;">​</a></h3><p>长撇要舒展而飘逸，短撇要迅速而有力。写好撇，是关键的是要撑握好角度和弧度。</p><h3 id="捺-如崩浪雷奔" tabindex="-1">捺：如崩浪雷奔 <a class="header-anchor" href="#捺-如崩浪雷奔" aria-label="Permalink to &quot;捺：如崩浪雷奔&quot;">​</a></h3><p>捺的出锋要重顿快收，力量要用得沉稳。斜捺是轻入笔，右下行笔出书锋，不要太直，忌生硬。</p><h3 id="折-如劲弩筋节" tabindex="-1">折：如劲弩筋节 <a class="header-anchor" href="#折-如劲弩筋节" aria-label="Permalink to &quot;折：如劲弩筋节&quot;">​</a></h3><p>折在书写时候，要有一个明显的停顿，然后转笔和力量的变化，方圆兼备。</p><h3 id="提-如策马扬鞭" tabindex="-1">提：如策马扬鞭 <a class="header-anchor" href="#提-如策马扬鞭" aria-label="Permalink to &quot;提：如策马扬鞭&quot;">​</a></h3><p>顿笔斜向上，形状像匕首，速度要快，有力量，有策马扬鞭的气势，但不要甩。</p><h3 id="勾-如百钧弩发" tabindex="-1">勾：如百钧弩发 <a class="header-anchor" href="#勾-如百钧弩发" aria-label="Permalink to &quot;勾：如百钧弩发&quot;">​</a></h3><p>横勾出钩迅速，钩身宜短，出锋方向指向字心。卧钩像一口锅，向上环抱。斜钩像一张弓，行笔迅疾，力拔山河。</p><p><img src="'+r+'" alt="图"></p>',17)])])}const m=e(n,[["render",s]]);export{_ as __pageData,m as default};
